mapper.sql:
p.batch_id=#{batchId}
AND (LOWER(p.full_name) LIKE #{searchPattern} ESCAPE chr(92) OR LOWER(COALESCE(p.participant_code,'')) LIKE #{searchPattern} ESCAPE chr(92)
OR LOWER(p.department_name) LIKE #{searchPattern} ESCAPE chr(92))
AND p.roster_status=#{rosterStatus}
AND p.attendance_status=#{attendanceStatus}
AND p.service_reconciliation_status=#{reconciliationStatus}

mapper.select:
SELECT FROM public.health_examination_batch_participants p JOIN public.health_examination_batch_days d ON d.batch_id=p.batch_id AND d.id=p.batch_day_id WHERE ORDER BY
p.full_name DESC, p.id DESC p.full_name ASC, p.id ASC p.participant_code DESC NULLS LAST, p.id DESC p.participant_code ASC NULLS LAST, p.id ASC d.examination_date DESC, p.id DESC d.examination_date ASC, p.id ASC p.id DESC p.id ASC
LIMIT #{limit} OFFSET #{offset}
